import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.CWgsre3x.js";const h=JSON.parse('{"title":"Ρύθμιση API παρόχων πληρωμών","description":"","frontmatter":{},"headers":[],"relativePath":"el/integrations/payment-api-setup.md","filePath":"el/integrations/payment-api-setup.md"}'),r={name:"el/integrations/payment-api-setup.md"};function i(c,e,l,n,_,p){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="ρυθμιση-api-παροχων-πληρωμων" tabindex="-1">Ρύθμιση API παρόχων πληρωμών <a class="header-anchor" href="#ρυθμιση-api-παροχων-πληρωμων" aria-label="Permalink to &quot;Ρύθμιση API παρόχων πληρωμών&quot;">​</a></h1><p>Έλεγχος πηγαίου κώδικα v0.7.26. Δεν επιβεβαιώνεται ενεργοποίηση παρόχου παραγωγής. Η καταγραφή μετρητών και εταιρικών τιμολογίων δεν είναι online έγκριση πληρωμής.</p><table tabindex="0"><thead><tr><th>Adapter</th><th>Ονόματα διαπιστευτηρίων στον κώδικα</th></tr></thead><tbody><tr><td>PayPal</td><td><code>PAYPAL_CLIENT_ID</code>, <code>PAYPAL_CLIENT_SECRET</code>, <code>PAYPAL_WEBHOOK_ID</code></td></tr><tr><td>Revolut</td><td><code>REVOLUT_API_KEY</code>, <code>REVOLUT_WEBHOOK_SECRET</code></td></tr><tr><td>Viva</td><td><code>VIVA_MERCHANT_ID</code>, <code>VIVA_API_KEY</code></td></tr><tr><td>Google Pay μέσω Viva</td><td>Κλειδιά Viva και <code>GOOGLE_PAY_MERCHANT_ID</code></td></tr><tr><td>Skrill</td><td><code>SKRILL_MERCHANT_EMAIL</code>, <code>SKRILL_SECRET_WORD</code>· προαιρετικό <code>SKRILL_API_URL</code></td></tr></tbody></table><p>Σημαντικό: το κείμενο ετοιμότητας Viva αναφέρει client ID/client secret και merchant source code, ενώ ο adapter χρησιμοποιεί merchant ID/API key. Απαιτείται τεχνική επαλήθευση και έλεγχος παρόχου πριν την ενεργοποίηση. Μην αντικαθιστάτε αυθαίρετα μορφές κλειδιών. Τα ονόματα δεν αποτελούν πλήρη ρύθμιση.</p><h2 id="ενταξη-εμπορου" tabindex="-1">Ένταξη εμπόρου <a class="header-anchor" href="#ενταξη-εμπορου" aria-label="Permalink to &quot;Ένταξη εμπόρου&quot;">​</a></h2><ol><li>Ανοίξτε επαληθευμένο εμπορικό λογαριασμό στην επίσημη πύλη. Ελέγξτε διακανονισμό EUR, αγορές, κόστος, sandbox και δικαιώματα API.</li><li>Ο εξουσιοδοτημένος διαχειριστής εγκαθιστά δοκιμαστικά κλειδιά στον διακομιστή. Μην εισάγετε μυστικά στην προβολή ετοιμότητας εταιρείας.</li><li>Ελέγξτε πραγματικά endpoints και περιβάλλον checkout, επιστροφές, υπογραφή callback και οδηγίες παρόχου. Ο κώδικας διαθέτει callbacks στο <code>/api/v1/webhooks/payments/:provider</code>. Το <code>PAYPAL_WEBHOOK_ENVIRONMENT</code> αφορά έλεγχο υπογραφής και δεν εγγυάται sandbox για όλα τα endpoints. Καμία πραγματική κλήση πριν επαληθευτεί ανεξάρτητα η απομόνωση.</li><li>Ελέγξτε ενεργοποίηση εταιρείας, ποσό/νόμισμα, υπογραφές, διπλά συμβάντα, ακύρωση, ανάκτηση και επιστροφές με εγκεκριμένες δοκιμές. PayPal και Revolut διαθέτουν διαδρομές επαλήθευσης· μην θεωρείτε ισοδύναμη κάλυψη όλων των παρόχων. Ο ελεγμένος adapter δεν υποστηρίζει επιστροφή Skrill.</li><li>Συμφωνήστε την πληρωμή με στοιχεία παρόχου πριν χαρακτηριστεί εξοφλημένη. Μην επαναλαμβάνετε χρέωση επειδή έληξε ο χρόνος αιτήματος. Απαιτείται γραπτή έγκριση για παραγωγή.</li></ol><p>Δείτε <a href="/el/integrations/payment-providers.html">Ετοιμότητα πληρωμών</a> και <a href="/el/developers/webhook-events.html">Webhook</a>.</p>',7)])])}const A=t(r,[["render",i]]);export{h as __pageData,A as default};
